import{c as a,S as r,j as t,m as o}from"./chunks/framework.C68YPdek.js";const p=JSON.parse('{"title":"Grader","description":"","frontmatter":{},"headers":[],"relativePath":"developer/architecture/grader.md","filePath":"developer/architecture/grader.md"}'),d={name:"developer/architecture/grader.md"};function s(n,e,i,h,c,l){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="grader" tabindex="-1">Grader <a class="header-anchor" href="#grader" aria-label="Permalink to “Grader”">​</a></h1><p><a href="https://github.com/source-academy/grader" target="_blank" rel="noreferrer"><code>grader</code></a> runs a submission&#39;s test cases and reports a score for each. It is a component of the <a href="./backend">backend</a>, runs as an AWS Lambda function, and <strong>knows no language</strong>: the language is whatever evaluator the event names. Checked against the repository&#39;s README on 28 November 2026.</p><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to “What it does”">​</a></h2><ol><li>It receives a JSON event from the backend. The event names the <a href="./conductor">Conductor</a> evaluator that grades the question (<code>library.evaluator</code>, an id from the <a href="./directories">language directory</a>), and carries the prepend, student and postpend programs and the test cases (a program, the expected answer and a score each).</li><li>For each test case it joins the prepend, student, postpend and test-case programs into one program and runs it in that evaluator, in a worker thread, under a Conductor host (<code>src/conductorGrader.ts</code>).</li><li>It returns a <code>Summary</code>: the total and maximum score and one result per test case: <code>pass</code>, <code>fail</code> (with the expected and the actual answer) or <code>error</code>. A test case&#39;s answer is compared with the last line the program prints.</li></ol><h2 id="the-evaluators-are-vendored" tabindex="-1">The evaluators are vendored <a class="header-anchor" href="#the-evaluators-are-vendored" aria-label="Permalink to “The evaluators are vendored”">​</a></h2><p>The grader keeps its own copy of the evaluators (<code>vendor/evaluators</code>, listed in <code>vendor/evaluators/manifest.json</code>), so that grading does not depend on the network. It refuses an event whose evaluator it does not have. To add or update one, <code>scripts/vendor-evaluator.sh</code> downloads it from the evaluator&#39;s GitHub Pages site (Source from js-slang, Python from py-slang, OCaml from ocaml-slang), and the manifest entry says how to load it. An evaluator that is updated and deployed for the browser is therefore <strong>not</strong> updated for grading until it is vendored again.</p><h2 id="where-to-read-more" tabindex="-1">Where to read more <a class="header-anchor" href="#where-to-read-more" aria-label="Permalink to “Where to read more”">​</a></h2><p>The README (the full input and output formats, the manifest fields, timeouts).</p>',8)])])}const m=a(d,[["render",s]]);export{p as __pageData,m as default};
